    // ------------------------------------------------------------------ FS 600/1000/1200
    private fun fs1000() = CatModel(
        brand = "علامة غير محددة (Generic)", country = "غير محدد", category = "الجراج",
        name = "FS 600 / FS 1000 / FS 1200 (فتّاحة جراج مفصلي/قلاب)", match = listOf("FS 600", "FS600", "FS 1000", "FS1000", "FS 1200"),
        controlUnit = "لوحة بشاشة رقمية وأزرار SET وCODE وUP وDOWN، ليمت إلكتروني، إضاءة LED 24V (15 LED)، أطراف: SD / GND / Flash / +24 / PE / GND / PB",
        specs = "FS600: دفع 600N، مساحة باب 10م²، وزن (متوازن) 80كغ • FS1000: 1000N، 15م²، 100كغ • FS1200: 1200N، 18م²، 130كغ • ارتفاع الباب 2400–3500مم • سلسلة/سير • سرعة 160مم/ث (FS1200: 140، ونسخة Speed: 200) • تغذية 220–240V / 110–127V • راديو 433.92MHz Rolling code • 50 ريموت • IP20 • −40 إلى +50°م • بداية ونهاية ناعمة",
        remoteInfo = "ريموتات Rolling code 433.92MHz حتى 50 ريموت، حفظ بزر CODE. الحذف الكامل بضغط CODE مطولًا. وظيفة تمييز الأزرار (9) تحدد هل ريموت واحد يشغّل أكثر من فتّاحة.",
        sensorsInfo = "فوتوسيل اختياري NC (وظيفة d) • نظام عائق بالقوة (1–5) • حماية الباب الصغير SD • فلاشر 24V • حافة لا توجد • بطارية احتياطية اختيارية",
        source = "Sectional and Tilting Door Opener FS 600/1000/1200 — Installation Instructions and User Guide (الشركة غير مذكورة)",
        guides = listOf(
